package com.neoenergia.cesar.neofluxo.exception;
import jakarta.persistence.EntityNotFoundException; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.security.authentication.BadCredentialsException; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(EntityNotFoundException.class) ResponseEntity<?> notFound(Exception e){return body(404,e.getMessage());} @ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class}) ResponseEntity<?> bad(Exception e){return body(400,e.getMessage());} @ExceptionHandler(BadCredentialsException.class) ResponseEntity<?> unauthorized(Exception e){return body(401,e.getMessage());} private ResponseEntity<?> body(int s,String m){return ResponseEntity.status(s).body(Map.of("timestamp",Instant.now(),"status",s,"message",m));}}
